use std::sync::{Arc, Mutex};
use std::thread;

struct Shared {
    c: i32,
    m: Mutex<()>,
    done: bool,
}

fn w2(shared: Arc<Mutex<Shared>>) {
    let guard = {
        let s = shared.lock().unwrap();
        let _g = s.m.lock().unwrap();
        // hold both locks; perform read-modify-write under m
        let mut s = s;
        let tmp = s.c;
        let tmp2 = tmp + 1;
        s.c = tmp2;
        // unlock m by dropping guard at end of scope
        drop(_g);
        drop(s);
        return;
    };
    let _ = guard;
}

