    let h1 = {
        let s = Arc::clone(&shared);
        thread::spawn(move || w2(s))
    };
    let h2 = {
        let s = Arc::clone(&shared);
        thread::spawn(move || w2(s))
    };
    h1.join().unwrap();
    h2.join().unwrap();
    {
        let mut s = shared.lock().unwrap();
        s.done = true;
    }
}

fn main() {
